#include "seed/online_ai.hpp"
#include <algorithm>
#include <cctype>
#include <cmath>
#include <sstream>
#include <utility>
namespace seed { namespace {
std::string esc(const std::string&v){std::ostringstream o;for(unsigned char c:v){switch(c){case '"':o<<"\\\"";break;case '\\':o<<"\\\\";break;case '\n':o<<"\\n";break;case '\r':o<<"\\r";break;case '\t':o<<"\\t";break;default:if(c<0x20){const char*h="0123456789abcdef";o<<"\\u00"<<h[c>>4]<<h[c&15];}else o<<static_cast<char>(c);}}return o.str();}
std::string trim(std::string s){while(!s.empty()&&s.back()=='/')s.pop_back();return s;}
std::string jstr(const std::string&b,const std::string&k,std::size_t from=0){const std::string n="\""+k+"\"";auto p=b.find(n,from);while(p!=std::string::npos){p=b.find(':',p+n.size());if(p==std::string::npos)return{};++p;while(p<b.size()&&std::isspace((unsigned char)b[p]))++p;if(p<b.size()&&b[p]=='"'){++p;std::string o;bool e=false;for(;p<b.size();++p){char c=b[p];if(e){switch(c){case 'n':o+='\n';break;case 'r':o+='\r';break;case 't':o+='\t';break;case '"':o+='"';break;case '\\':o+='\\';break;case '/':o+='/';break;default:o+=c;}e=false;}else if(c=='\\')e=true;else if(c=='"')return o;else o+=c;}return{};}p=b.find(n,p);}return{};}
std::uint64_t jnum(const std::string&b,const std::string&k){auto p=b.find("\""+k+"\"");if(p==std::string::npos)return 0;p=b.find(':',p);if(p==std::string::npos)return 0;while(++p<b.size()&&std::isspace((unsigned char)b[p])){}std::uint64_t n=0;bool any=false;while(p<b.size()&&std::isdigit((unsigned char)b[p])){any=true;n=n*10+(unsigned)(b[p++]-'0');}return any?n:0;}
std::string role(ChatRole r){return r==ChatRole::Assistant?"assistant":r==ChatRole::System?"system":"user";}
std::string openMessages(const ChatRequest&r){std::string o="[";bool f=true;for(const auto&m:r.messages){if(!f)o+=',';f=false;o+="{\"role\":\""+role(m.role)+"\",\"content\":\""+esc(m.content)+"\"}";}return o+"]";}
class JsonProvider final:public ProviderAdapter{ProviderKind k_;std::string extract(const std::string&b)const{if(k_==ProviderKind::OpenAICompatible){auto p=b.find("\"message\"");auto s=jstr(b,"content",p==std::string::npos?0:p);return s.empty()?jstr(b,"content"):s;}if(k_==ProviderKind::Anthropic){auto p=b.find("\"content\"");auto s=jstr(b,"text",p==std::string::npos?0:p);return s.empty()?jstr(b,"text"):s;}auto p=b.find("\"parts\"");auto s=jstr(b,"text",p==std::string::npos?0:p);return s.empty()?jstr(b,"text"):s;}
public:explicit JsonProvider(ProviderKind k):k_(k){}ProviderKind kind()const noexcept override{return k_;}
ProviderResult generate(const ProviderConfig&c,const ChatRequest&r,const HttpTransport&t,const CredentialVault&v)const override{ProviderResult out;if(c.kind!=k_||!c.enabled){out.error="Provider kind mismatch or provider disabled.";return out;}if(r.messages.empty()||r.maxOutputTokens==0||r.maxOutputTokens>32768||!std::isfinite(r.temperature)||r.temperature<0||r.temperature>2){out.error="Chat request is invalid.";return out;}std::string e;if(!isSafeProviderUrl(c,e)){out.error=e;return out;}std::string key;if(c.credentialRef.empty()||!v.getSecret(c.credentialRef,key)||key.empty()){out.error="Provider credential is missing from the configured credential vault.";return out;}HttpRequest q;q.timeoutMs=std::clamp(c.timeoutMs,1000U,180000U);q.maxResponseBytes=std::clamp<std::size_t>(c.maxResponseBytes,1024U,8U*1024U*1024U);q.headers["Content-Type"]="application/json";const auto base=trim(c.baseUrl);
if(k_==ProviderKind::OpenAICompatible){q.url=base+"/chat/completions";q.headers["Authorization"]="Bearer "+key;q.body="{\"model\":\""+esc(c.model)+"\",\"messages\":"+openMessages(r)+",\"max_tokens\":"+std::to_string(r.maxOutputTokens)+",\"temperature\":"+std::to_string(r.temperature)+"}";}
else if(k_==ProviderKind::Anthropic){q.url=base+"/v1/messages";q.headers["x-api-key"]=key;q.headers["anthropic-version"]="2023-06-01";std::string sys,msg="[";bool f=true;for(const auto&m:r.messages){if(m.role==ChatRole::System){if(!sys.empty())sys+='\n';sys+=m.content;continue;}if(!f)msg+=',';f=false;msg+="{\"role\":\""+std::string(m.role==ChatRole::Assistant?"assistant":"user")+"\",\"content\":\""+esc(m.content)+"\"}";}msg+="]";q.body="{\"model\":\""+esc(c.model)+"\",\"max_tokens\":"+std::to_string(r.maxOutputTokens)+",\"temperature\":"+std::to_string(r.temperature)+",\"messages\":"+msg;if(!sys.empty())q.body+=",\"system\":\""+esc(sys)+"\"";q.body+="}";}
else{q.url=base+"/v1beta/models/"+c.model+":generateContent";q.headers["x-goog-api-key"]=key;std::string sys,contents="[";bool f=true;for(const auto&m:r.messages){if(m.role==ChatRole::System){if(!sys.empty())sys+='\n';sys+=m.content;continue;}if(!f)contents+=',';f=false;contents+="{\"role\":\""+std::string(m.role==ChatRole::Assistant?"model":"user")+"\",\"parts\":[{\"text\":\""+esc(m.content)+"\"}]}";}contents+="]";q.body="{\"contents\":"+contents+",\"generationConfig\":{\"maxOutputTokens\":"+std::to_string(r.maxOutputTokens)+",\"temperature\":"+std::to_string(r.temperature)+"}";if(!sys.empty())q.body+=",\"systemInstruction\":{\"parts\":[{\"text\":\""+esc(sys)+"\"}]}";q.body+="}";}
HttpResponse response;std::string te;if(!t.postJson(q,response,te)){out.error=te.empty()?"Network request failed.":te;return out;}if(response.body.size()>q.maxResponseBytes){out.error="Provider response exceeded the configured size limit.";return out;}if(response.statusCode<200||response.statusCode>=300){out.error="Provider returned HTTP "+std::to_string(response.statusCode)+".";return out;}out.text=extract(response.body);if(out.text.empty()){out.error="Provider response did not contain a supported text candidate.";return out;}if(k_==ProviderKind::OpenAICompatible){out.usage.inputTokens=jnum(response.body,"prompt_tokens");out.usage.outputTokens=jnum(response.body,"completion_tokens");}else if(k_==ProviderKind::Anthropic){out.usage.inputTokens=jnum(response.body,"input_tokens");out.usage.outputTokens=jnum(response.body,"output_tokens");}else{out.usage.inputTokens=jnum(response.body,"promptTokenCount");out.usage.outputTokens=jnum(response.body,"candidatesTokenCount");}out.usage.reportedByProvider=out.usage.inputTokens>0||out.usage.outputTokens>0;out.success=true;return out;}
};}
bool isSafeProviderUrl(const ProviderConfig&c,std::string&e){const auto&u=c.baseUrl;bool https=u.rfind("https://",0)==0;bool local=u.rfind("http://localhost",0)==0||u.rfind("http://127.0.0.1",0)==0||u.rfind("http://10.",0)==0||u.rfind("http://192.168.",0)==0;if(u.empty()||u.size()>2048||u.find_first_of("\r\n")!=std::string::npos){e="Provider base URL is empty or invalid.";return false;}if(!https&&!(c.allowInsecureLocalhost&&local)){e="HTTPS is required; cleartext HTTP is allowed only for explicitly enabled local endpoints.";return false;}if(c.model.empty()||c.model.size()>256||c.model.find_first_of("\r\n")!=std::string::npos){e="A valid model identifier is required.";return false;}e.clear();return true;}
bool ProviderRegistry::add(ProviderConfig c,std::string&e){if(c.id.empty()||c.id.size()>96||c.displayName.empty()||c.displayName.size()>128||c.credentialRef.empty()){e="Provider id, display name and credential reference are required.";return false;}if(!isSafeProviderUrl(c,e))return false;if(find(c.id)){e="Provider id already exists.";return false;}providers_.push_back(std::move(c));e.clear();return true;}
bool ProviderRegistry::remove(const std::string&id){auto i=std::find_if(providers_.begin(),providers_.end(),[&](const auto&p){return p.id==id;});if(i==providers_.end())return false;providers_.erase(i);return true;}
const ProviderConfig*ProviderRegistry::find(const std::string&id)const noexcept{auto i=std::find_if(providers_.begin(),providers_.end(),[&](const auto&p){return p.id==id;});return i==providers_.end()?nullptr:&*i;}
std::vector<ProviderConfig>ProviderRegistry::enabled()const{std::vector<ProviderConfig>o;for(const auto&p:providers_)if(p.enabled)o.push_back(p);return o;}
std::size_t ProviderRegistry::size()const noexcept{return providers_.size();}
RouteDecision ProviderRouter::choose(bool local,bool online,bool net,const ProviderRegistry&r){if(local)return{RouteTarget::Local,{},"Local model is ready; local-first policy selected it."};if(!online)return{RouteTarget::Unavailable,{},"Online providers are disabled by operator settings."};if(!net)return{RouteTarget::Unavailable,{},"No network is available and no local model is ready."};auto p=r.enabled();if(p.empty())return{RouteTarget::Unavailable,{},"No enabled online provider is configured."};return{RouteTarget::Online,p.front().id,"Local model unavailable; online fallback is explicitly enabled."};}
std::unique_ptr<ProviderAdapter>makeProviderAdapter(ProviderKind k){return std::make_unique<JsonProvider>(k);}
}
